const TRIGGER_CODE = `// IntegrationHub.publish takes a List, never a Set or a Map. Two forms:
//   List<Id> publish(String eventKey, List<SObject> records)   records need an Id (after insert / update)
//   List<Id> publish(String eventKey, List<Id> recordIds)
// It returns the Ids of the transactions it created (empty when nothing was sent).

List<Case> webCases = new List<Case>();          // filled in your handler where the condition is met
IntegrationHub.publish('CASE_WEB_CREATED', webCases);

// From a Set or a Map, convert to a List:
Set<Id> caseIds = new Set<Id>();
IntegrationHub.publish('CASE_WEB_CREATED', new List<Id>(caseIds));

Map<Id, Case> casesById = new Map<Id, Case>();
IntegrationHub.publish('CASE_WEB_CREATED', casesById.values());`;

const RESPONSE_CODE = `// 1. Create this class (any name), 2. type its name in the event's Response Handler Class field.
public with sharing class CaseReplyHandler implements IntegrationHub.IResponseHandler {
    public void handle(IntegrationHub.ResponseContext ctx) {
        // ctx.isCallback      false = the immediate HTTP reply, true = the callback
        // ctx.body            the reply or callback JSON (text)
        // ctx.httpStatus      HTTP status of the reply (null on the callback)
        // ctx.relatedRecordId the record that was sent (e.g. the Case)
        // ctx.txn             the Integration Transaction (Status__c, External_Reference_Id__c ...)
        // ctx.data            the parsed "data" object of the reply or callback (null when there is none)
        // ctx.result          set a short line here; it is shown as Business Result on the transaction
        if (String.isBlank(ctx.body) || ctx.relatedRecordId == null) {
            return;
        }
        Object parsed = JSON.deserializeUntyped(ctx.body);
        if (!(parsed instanceof Map<String, Object>)) {
            return;
        }
        Map<String, Object> body = (Map<String, Object>) parsed;
        // Your process here, for example copy a value to the Case:
        // update new Case(Id = ctx.relatedRecordId, Your_Field__c = (String) body.get('reference'));
    }
}`;

const INBOUND_HANDLER_CODE = `// 1. Create this class (any name), 2. type its name in the inbound event's Handler Class field.
public with sharing class CaseCreateHandler implements IntegrationHub.IInboundHandler {
    public IntegrationHub.InboundResult handle(IntegrationHub.InboundContext ctx) {
        Map<String, Object> req = ctx.data;   // the JSON body, parsed
        if (req == null || req.get('subject') == null) {
            return IntegrationHub.inboundFailure(400, 'subject is required');
        }
        Case c = new Case(Subject = (String) req.get('subject'), Origin = 'Web');
        insert c;
        return IntegrationHub.inboundSuccess(c.Id, new Map<String, Object>{ 'caseId' => c.Id });
    }
}`;

const PAYLOAD_CLASS_CODE = `// Payload Source = Apex Class: 1. create this class (any name), 2. type its name in the event's Payload Class field.
public with sharing class CasePayloadBuilder implements IntegrationHub.IPayloadBuilder {
    public Map<Id, Object> build(IntegrationHub.PayloadRequest req) {
        // req.recordIds: every record of this send, as one list (query them once)
        // req.transactionIdByRecordId, req.eventKey, req.relatedObject
        Map<Id, Object> bodies = new Map<Id, Object>();
        for (Case c : [SELECT Id, CaseNumber, Subject, Account.Name FROM Case WHERE Id IN :req.recordIds]) {
            bodies.put(c.Id, new Map<String, Object>{
                'caseNumber' => c.CaseNumber,
                'title' => c.Subject,
                'customer' => c.Account.Name
            });
        }
        // A Map body gets sfTransactionId added for you. A String body is sent exactly as returned.
        return bodies;
    }
}`;

