const EXAMPLES_CODE = `// Part 1: run the outbound examples once (Self Org, sandbox). Sends run in the background:
// wait a few seconds, then look at the Transactions tab or the Monitor.
List<Case> cases = [SELECT Id, CaseNumber FROM Case WHERE Subject != null ORDER BY CreatedDate DESC LIMIT 1];
List<Account> accounts = [SELECT Id, Name FROM Account ORDER BY CreatedDate DESC LIMIT 1];
List<String> caseEvents = new List<String>{
    'SELF_SEND_OK', 'SELF_SEND_CALLBACK', 'SELF_SEND_CLASS', 'SELF_SEND_REJECT',
    'SELF_SEND_DOWN', 'SELF_SEND_CREATE_CASE', 'SELF_SEND_TOKENS'
};
if (cases.isEmpty()) {
    System.debug(LoggingLevel.WARN, 'No Case with a Subject found.');
} else {
    List<Id> caseIds = new List<Id>{ cases[0].Id };
    System.debug(LoggingLevel.INFO, 'Case: ' + cases[0].CaseNumber);
    for (String eventKey : caseEvents) {
        List<Id> txnIds = IntegrationHub.publish(eventKey, caseIds);
        System.debug(LoggingLevel.INFO, eventKey + ' transaction ids: ' + txnIds);
    }
}
if (accounts.isEmpty()) {
    System.debug(LoggingLevel.WARN, 'No Account found.');
} else {
    List<Id> txnIds = IntegrationHub.publish('SELF_SEND_ACCOUNT', new List<Id>{ accounts[0].Id });
    System.debug(LoggingLevel.INFO, 'SELF_SEND_ACCOUNT (' + accounts[0].Name + ') transaction ids: ' + txnIds);
}

// Part 2: the callback for SELF_SEND_CALLBACK. Run it on its own (not together with Part 1)
// once that transaction shows Sent. Same as:
// PATCH {My Domain}/services/apexrest/integrationhub/v1/callback/{sfTransactionId}
// { "status": "SUCCESS", "reference": "SELF-001", "message": "Done" }
List<IH_Transaction__c> txns = [SELECT Id FROM IH_Transaction__c
    WHERE Event_Name__c = 'SELF_SEND_CALLBACK' AND Status__c = 'Sent' ORDER BY CreatedDate DESC LIMIT 1];
if (txns.isEmpty()) {
    System.debug(LoggingLevel.WARN, 'No Sent SELF_SEND_CALLBACK transaction; run Part 1 and wait.');
} else {
    HttpRequest req = new HttpRequest();
    req.setEndpoint('callout:IH_Self_Org/services/apexrest/integrationhub/v1/callback/' + txns[0].Id);
    req.setMethod('PATCH');
    req.setHeader('Content-Type', 'application/json');
    req.setBody(JSON.serialize(new Map<String, Object>{
        'status' => 'SUCCESS', 'reference' => 'SELF-001', 'message' => 'Done' }));
    HttpResponse res = new Http().send(req);
    System.debug(LoggingLevel.INFO, 'Callback ' + txns[0].Id + ': ' + res.getStatusCode() + ' ' + res.getBody());
}`;

