const BUSINESS_HANDLER_CODE = `// Event: tick Business Data In Response and type this class name in Response Handler Class.
// Runs in the background (Queueable). It can run more than once on the same data: update or upsert, never a blind insert.
public with sharing class VoucherHandler implements IntegrationHub.IResponseHandler {
    public void handle(IntegrationHub.ResponseContext ctx) {
        if (ctx.data == null || ctx.relatedRecordId == null) {
            ctx.result = 'No data';
            return;
        }
        String voucher = (String) ctx.data.get('voucherNumber');
        update new Case(Id = ctx.relatedRecordId, Voucher_Number__c = voucher);
        ctx.result = 'Voucher ' + voucher + ' saved on the Case';
        // An exception here sets Business Status = Failed; an admin can use Rerun handler after the fix.
    }
}`;

const AUTH_CODE = `// Connection: Connection Type = Apex Auth, Auth Class = this class. The Named Credential stays: it gives the URL.
// No secret in code or in a field: the login goes through a Named Credential (here Partner_Login) whose External
// Credential holds the client Id and secret (tick "Allow Formulas in HTTP Body" on it for the merge fields below).
public with sharing class PartnerAuth implements IntegrationHub.IConnectionAuth {
    public void authorize(IntegrationHub.AuthContext ctx) {
        // ctx.request     the request about to be sent: set the login header on it
        // ctx.connection  the connection (Id, Name, Named_Credential__c, Auth_Class__c)
        // ctx.refresh     true after a 401: log in again, do not use the cached token
        // ctx.eventKey    the event being sent (null for Check connection)
        String token = ctx.refresh ? null : IntegrationHubTokenCache.cachedToken(ctx.connection.Id);
        if (token == null) {
            HttpRequest login = new HttpRequest();
            login.setEndpoint('callout:Partner_Login/oauth/token');
            login.setMethod('POST');
            login.setHeader('Content-Type', 'application/x-www-form-urlencoded');
            login.setBody('grant_type=client_credentials&client_id={!$Credential.Partner_Login.ClientId}'
                + '&client_secret={!$Credential.Partner_Login.ClientSecret}');
            Map<String, Object> answer = (Map<String, Object>) JSON.deserializeUntyped(new Http().send(login).getBody());
            token = (String) answer.get('access_token');
            Integer seconds = Integer.valueOf(answer.get('expires_in'));
            // Kept for this job, and in Platform Cache (default partition) when the org has it.
            IntegrationHubTokenCache.putToken(ctx.connection.Id, token, seconds - 60);
        }
        ctx.request.setHeader('Authorization', 'Bearer ' + token);
        // A CalloutException (token URL down or timed out) is temporary: auto-retry applies. Any other exception
        // fails the transaction for good (permanent) with your message.
    }
}`;

