const YES_NO = [
    { label: 'Yes', value: 'yes' },
    { label: 'No', value: 'no' }
];

const STORE_LAST = 'ihHowTo.lastTopic';
const STORE_VISITED = 'ihHowTo.visited';
const NARROW_PX = 800;

// Download buttons of a step: its template class and test, or its listed files. All live in IH_Help/samples.
function downloadsOf(s) {
    const file = (label, name) => ({ key: s.key + name, label, name, href: IH_HELP + '/samples/' + name });
    if (s.files) {
        return s.files.map((f) => file(f.label, f.file));
    }
    return s.template
        ? [file('Download class', s.template + '.cls'), file('Download test class', s.template + 'Test.cls')]
        : [];
}

// Browser storage may be blocked (private window, preview): every access is guarded, the page works without it.
function readStore(key) {
    try {
        return window.localStorage.getItem(key);
    } catch (e) {
        return null;
    }
}

function writeStore(key, value) {
    try {
        window.localStorage.setItem(key, value);
    } catch (e) {
        // ignore: storage is a convenience only
    }
}

function readVisited() {
    try {
        const list = JSON.parse(readStore(STORE_VISITED) || '[]');
        return Array.isArray(list) ? list.filter((k) => TOPICS.some((t) => t.key === k)) : [];
    } catch (e) {
        return [];
    }
}

function tableView(table, prefix) {
    const mono = table.mono || [];
    return {
        key: prefix,
        title: table.title,
        hasTitle: Boolean(table.title),
        cols: table.columns.map((c, i) => ({ key: prefix + 'c' + i, label: c })),
        rows: table.rows.map((r, ri) => ({
            key: prefix + 'r' + ri,
            cells: r.map((text, ci) => ({
                key: prefix + 'r' + ri + 'c' + ci,
                text,
                cls: mono.includes(ci) ? 'ih-mono cell' : 'cell'
            }))
        }))
    };
}

function searchText(t) {
    const parts = [t.short, t.title, t.lead || ''].concat(t.points || []);
    (t.tables || []).forEach((tb) => tb.rows.forEach((r) => parts.push(r.join(' '))));
    return parts.join(' ').toLowerCase();
}

const CODE_BY_KEY = {};
TOPICS.forEach((t) => (t.codes || []).forEach((c, i) => {
    CODE_BY_KEY[t.key + '-code' + i] = c;
}));
const SEARCH_INDEX = TOPICS.map((t) => searchText(t));

/**
 * How to use Integration Hub: a stepper index on the left, one topic on the right, copyable code. Apex only in the
 * embedded c/ihUsage (What's implemented & usage, Who uses Integration Hub; admins).
 * Works as a tab, on an app or home page, or on a record page.
 */
export default class IhHowTo extends NavigationMixin(LightningElement) {
    @wire(IsConsoleNavigation) isConsole;
    @wire(EnclosingTabId) tabId;

    currentKey = TOPICS[0].key;
    visited = [];
    query = '';
    narrow = false;
    answers = {};
    resizeObserver;
    observed = false;
    scrollPending = false;

    connectedCallback() {
        const last = readStore(STORE_LAST);
        if (last && TOPICS.some((t) => t.key === last)) {
            this.currentKey = last;
        }
        this.visited = readVisited();
        this.markVisited(this.currentKey);
        try {
            this.narrow = window.innerWidth < NARROW_PX;
        } catch (e) {
            this.narrow = false;
        }
    }

    renderedCallback() {
        if (!this.observed) {
            this.observed = true;
            this.observeWidth();
        }
        if (this.scrollPending) {
            this.scrollPending = false;
            this.scrollToPane();
        }
    }

    disconnectedCallback() {
        if (this.resizeObserver) {
            try {
                this.resizeObserver.disconnect();
            } catch (e) {
                // ignore
            }
            this.resizeObserver = null;
        }
        this.observed = false;
    }

    observeWidth() {
        const root = this.template.querySelector('.how');
        if (!root) {
            this.observed = false;
            return;
        }
        try {
            // eslint-disable-next-line no-undef
            this.resizeObserver = new ResizeObserver((entries) => {
                const width = entries && entries[0] ? entries[0].contentRect.width : root.clientWidth;
                const narrow = width > 0 && width < NARROW_PX;
                if (narrow !== this.narrow) {
                    this.narrow = narrow;
                }
            });
            this.resizeObserver.observe(root);
        } catch (e) {
            this.narrow = root.clientWidth > 0 && root.clientWidth < NARROW_PX;
        }
    }

    scrollToPane() {
        try {
            const pane = this.template.querySelector('.pane');
            if (pane && pane.getBoundingClientRect().top < 0) {
                pane.scrollIntoView({ block: 'start', behavior: 'smooth' });
            }
        } catch (e) {
            // ignore
        }
    }

    markVisited(key) {
        if (!this.visited.includes(key)) {
            this.visited = [...this.visited, key];
            writeStore(STORE_VISITED, JSON.stringify(this.visited));
        }
    }

    select(key) {
        if (!key || !TOPICS.some((t) => t.key === key)) {
            return;
        }
        this.currentKey = key;
        this.markVisited(key);
        writeStore(STORE_LAST, key);
        this.scrollPending = true;
    }

    // ---------- index ----------

    /** The How To as one PDF book, made from this content when the package is built (IH_Help). */
    get pdfUrl() {
        return IH_HELP + '/IntegrationHub_HowTo.pdf';
    }

    get matchingKeys() {
        const q = this.query.trim().toLowerCase();
        if (!q) {
            return null;
        }
        const words = q.split(/\s+/);
        return TOPICS.filter((t, i) => words.every((w) => SEARCH_INDEX[i].includes(w))).map((t) => t.key);
    }

    get groups() {
        const matching = this.matchingKeys;
        const current = this.currentTopic;
        const out = [];
        GROUPS.forEach((g, gi) => {
            const all = TOPICS.filter((t) => t.group === g.key);
            const shown = matching ? all.filter((t) => matching.includes(t.key)) : all;
            if (!shown.length) {
                return;
            }
            const isCurrent = current.group === g.key;
            const read = all.every((t) => this.visited.includes(t.key));
            let state = 'todo';
            if (isCurrent) {
                state = 'current';
            } else if (read) {
                state = 'read';
            }
            out.push({
                key: g.key,
                name: g.name,
                badge: g.badge,
                showTick: state === 'read',
                firstKey: shown[0].key,
                cls: 'group group_' + state + (read ? ' group_done' : '') + (gi === GROUPS.length - 1 ? ' group_last' : ''),
                topics: shown.map((t) => {
                    const on = t.key === this.currentKey;
                    const seen = this.visited.includes(t.key);
                    return {
                        key: t.key,
                        label: t.short,
                        ariaCurrent: on ? 'page' : null,
                        cls: 'topic' + (on ? ' topic_on' : '') + (seen ? ' topic_seen' : '')
                    };
                })
            });
        });
        return out;
    }

    get noMatch() {
        return this.groups.length === 0;
    }

    get progressText() {
        return this.visited.length + ' of ' + TOPICS.length + ' topics read';
    }

    get topicOptions() {
        return TOPICS.map((t) => {
            const g = GROUPS.find((x) => x.key === t.group);
            return { label: g.badge + ' · ' + g.name + ' › ' + t.short, value: t.key };
        });
    }

    get wideClass() {
        return this.narrow ? 'how how_narrow' : 'how';
    }

    get showIndex() {
        return !this.narrow;
    }

    // ---------- current topic ----------

    get currentIndex() {
        const i = TOPICS.findIndex((t) => t.key === this.currentKey);
        return i < 0 ? 0 : i;
    }

    get currentTopic() {
        return TOPICS[this.currentIndex];
    }

    get topic() {
        const t = this.currentTopic;
        const g = GROUPS.find((x) => x.key === t.group);
        const downloads = downloadsOf(t);
        // A live table's static version is for the PDF book and readers; admins see the live one in c/ihUsage.
        const tables = (t.tables || []).map((tb, i) => (tb.live && IS_ADMIN ? null : tableView(tb, t.key + 't' + i))).filter(Boolean);
        return {
            key: t.key,
            title: t.title,
            lead: t.lead,
            hasLead: Boolean(t.lead),
            crumb: g.badge + ' · ' + g.name + ' › ' + t.short,
            points: (t.points || []).map((text, i) => ({ key: t.key + 'p' + i, text })),
            hasPoints: Boolean(t.points && t.points.length),
            tables,
            hasTables: tables.length > 0,
            codes: (t.codes || []).map((c, i) => ({ key: t.key + '-code' + i, label: c.label, code: c.code })),
            hasCodes: Boolean(t.codes && t.codes.length),
            pictures: (t.images || []).map((img) => ({ key: img.file, src: IH_HELP + '/' + img.file, caption: img.caption })),
            hasImages: Boolean(t.images),
            downloads,
            hasDownloads: downloads.length > 0,
            downloadNote: t.filesNote || 'Template to start from: a ready-to-deploy class and its test class. Rename both, change the marked parts, deploy.',
            tip: t.tip,
            hasTip: Boolean(t.tip),
            isChooser: Boolean(t.chooser),
            embedConfigTransfer: Boolean(t.embedConfigTransfer),
            hasUsage: Boolean(t.usage),
            usage: t.usage,
            hasGo: Boolean(t.tab || t.object),
            go: t.go,
            target: t.tab || t.object,
            kind: t.object ? 'object' : 'tab'
        };
    }

    get prevTopic() {
        const i = this.currentIndex;
        return i > 0 ? { key: TOPICS[i - 1].key, label: TOPICS[i - 1].short } : null;
    }

    get nextTopic() {
        const i = this.currentIndex;
        return i < TOPICS.length - 1 ? { key: TOPICS[i + 1].key, label: TOPICS[i + 1].short } : null;
    }

    /** Static facts for c/ihUsage (jobs, components it cannot read from Apex). */
    get usageInfo() {
        return USAGE_INFO;
    }

    // ---------- chooser ----------

    get questions() {
        return QUESTIONS.map((q, i) => ({
            key: q.key,
            label: (i + 1) + '. ' + q.text,
            value: this.answers[q.key] || null
        }));
    }

    get yesNo() {
        return YES_NO;
    }

    get chooserRows() {
        return QUESTIONS.filter((q) => this.answers[q.key]).map((q) => {
            const pick = q[this.answers[q.key]];
            const target = TOPICS.find((t) => t.key === pick.topic);
            return {
                key: q.key,
                field: pick.field,
                topicKey: pick.topic,
                hasTopic: Boolean(target),
                topicLabel: target ? target.short : ''
            };
        });
    }

    get hasChooserRows() {
        return this.chooserRows.length > 0;
    }

    get chooserDone() {
        return QUESTIONS.every((q) => this.answers[q.key]);
    }

    handleAnswer(event) {
        const key = event.target.dataset.key;
        this.answers = { ...this.answers, [key]: event.detail.value };
    }

    handleResetChooser() {
        this.answers = {};
    }

    // ---------- events ----------

    handlePick(event) {
        this.select(event.currentTarget.dataset.key);
    }

    handleCombo(event) {
        this.select(event.detail.value);
    }

    handleSearch(event) {
        this.query = event.target.value || '';
    }

    handleOpenChooser() {
        this.select('chooser');
    }

    handlePrev() {
        if (this.prevTopic) {
            this.select(this.prevTopic.key);
        }
    }

    handleNext() {
        if (this.nextTopic) {
            this.select(this.nextTopic.key);
        }
    }

    handleResetProgress() {
        this.visited = [this.currentKey];
        writeStore(STORE_VISITED, JSON.stringify(this.visited));
    }

    handleGo(event) {
        const { target, kind } = event.currentTarget.dataset;
        const page = kind === 'object' ? objectListPage(target) : tabPage(target);
        openPage(this, page, { isConsole: this.isConsole, tabId: this.tabId, asWorkspaceTab: true });
    }

    async handleCopy(event) {
        const block = CODE_BY_KEY[event.currentTarget.dataset.key];
        let ok = false;
        try {
            await navigator.clipboard.writeText(block.code);
            ok = true;
        } catch (e) {
            ok = false;
        }
        this.dispatchEvent(new ShowToastEvent({
            title: ok ? 'Copied' : 'Copy not available',
            message: ok ? block.label + ' copied.' : 'Select the code and copy it with your keyboard.',
            variant: ok ? 'success' : 'warning'
        }));
    }
}
